        "/api/olist/reports/{report_name}/": {
            "get": {
                "operationId": "olist_reports_retrieve",
                "description": "Administrator-only historical SQL report, page size 20. Sales use snapshot delivered status; source purchase timestamps have no verified time zone. See docs/stage-05/sql-portfolio.md for each result grain and NULL rules.",
                "parameters": [
                    {
                        "in": "query",
                        "name": "end",
                        "schema": {
                            "type": "string",
                            "default": "2018-11-01 00:00:00"
                        },
                        "description": "Exclusive source timestamp; increasing interval up to ten years."
                    },
                    {
                        "in": "query",
                        "name": "min_orders",
                        "schema": {
                            "type": "integer",
                            "default": 2
                        },
                        "description": "Repeat threshold, 2 to 1000000."
                    },
                    {
                        "in": "query",
                        "name": "min_units",
                        "schema": {
                            "type": "integer",
                            "default": 10
                        },
                        "description": "Unit threshold, 1 to 1000000."
                    },
                    {
                        "in": "query",
                        "name": "page",
                        "schema": {
                            "type": "integer"
                        },
                        "description": "Page number, starting at 1."
                    },
                    {
                        "in": "path",
                        "name": "report_name",
                        "schema": {
                            "type": "string",
                            "enum": [
                                "best_selling_products",
                                "category_seller_sales",
                                "customer_coverage",
                                "customer_spending",
                                "delivery_performance",
                                "monthly_sales",
                                "order_details",
                                "reconciliation",
                                "repeat_customer_rate",
                                "repeat_customers",
                                "running_monthly_totals",
                                "seller_delivery"
                            ]
                        },
                        "required": true
                    },
                    {
                        "in": "query",
                        "name": "start",
                        "schema": {
                            "type": "string",
                            "default": "2016-09-01 00:00:00"
                        },
